    targlen = dwarfstring_strlen(target);
    inputs = dwarfstring_string(&winput);
    if (!targlen) {
        dwarfstring_append(target,inputs);
        return DW_DLV_OK;
    }
#else /* !_Windows */
    targlen = dwarfstring_strlen(target);
#endif /* _WIN32 */

